Running command: cd /workspace && cat > test_fuzz.c << 'EOF'
#include <stdint.h>
#include <stddef.h>
#include <string.h>
#include <stdio.h>

/* Forward declaration */
int fuzz_parse_http_request(const uint8_t *data, size_t length);

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <poc_file>\n", argv[0]);
        return 1;
    }

    FILE *f = fopen(argv[1], "rb");
    if (!f) {
        fprintf(stderr, "Cannot open %s\n", argv[1]);
        return 1;
    }

    fseek(f, 0, SEEK_END);
    long len = ftell(f);
    fseek(f, 0, SEEK_SET);

    if (len > 32767) len = 32767;

    uint8_t *data = new uint8_t[len];
    fread(data, 1, len, f);
    fclose(f);

    printf("Calling fuzz_parse_http_request with %ld bytes...\n", len);
    fflush(stdout);

    int result = fuzz_parse_http_request(data, len);

    printf("Result: %d\n", result);
    delete[] data;
    return 0;
}
EOF
echo "Test file created"

